locals {
  # Convention de tags appliquée partout (principe DRY)
  common_tags = {
    Project     = var.project
    Environment = var.environment
    ManagedBy   = "terraform"
  }
  # Un préfixe de nommage réutilisable, ex. "boutique-prod"
  name_prefix = "${var.project}-${var.environment}"
}

resource "aws_instance" "web" {
  # ...
  # merge(...) fusionne deux maps : ici les tags communs + un tag Name propre.
  tags = merge(local.common_tags, { Name = "${local.name_prefix}-web" })
}

output "load_balancer_url" {
  description = "URL publique de l'application"
  value       = aws_lb.main.dns_name
}

output "db_password" {
  value     = aws_db_instance.main.password
  sensitive = true          # masqué à l'affichage (mais présent dans le state)
}

# Vérifier une hypothèse avant l'apply
resource "aws_instance" "web" {
  # ...
  lifecycle {
    precondition {
      condition     = data.aws_ami.selected.architecture == "x86_64"
      error_message = "L'AMI doit être x86_64."
    }
  }
}

locals {
  # produire toutes les combinaisons app x zone, en une map à clé unique
  deployments = {
    for pair in flatten([
      for app in var.apps : [
        for az in var.zones : { app = app, az = az }
      ]
    ]) : "${pair.app}-${pair.az}" => pair
  }
}

resource "aws_instance" "srv" {
  for_each          = local.deployments      # une instance par combinaison
  availability_zone = each.value.az
  tags = { Name = each.key }
}
